STORY=[]

def para(t,kind='body'):
 return Paragraph(t,styles[kind])
def p(t): STORY.append(para(t))
def h(t): STORY.append(para(t,'h2'))
def section(title):
 if STORY: STORY.append(PageBreak())
 STORY.append(para(title,'h1'))
def simple_table(rows,widths=[160,590]):
 t=Table([[para(escape(str(v)), 'thead' if i==0 else 'cell') for v in row] for i,row in enumerate(rows)],colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),PALE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,0),(-1,-1),0.3,BORDER)]))
 STORY.append(t);STORY.append(Spacer(1,10))

