def explain(file,n,line):
 if n in MAP.get(file,{}): return MAP[file][n]
 t=line.strip()
 if not t:return 'Blank source line separating logical sections; it has no runtime effect.'
 if t.startswith('package '): return 'Places this file in the '+t[8:]+' Kotlin namespace.'
 if t.startswith('import '):
  name=t[7:].split('.')[-1]
  if name in IMPORTS:return 'Imports '+IMPORTS[name]
  if name=='*':return 'Imports the members of '+t[7:-2]+' used by the UI or state code in this file.'
  return 'Imports '+name+' so this file can use that existing app class or composable by its short name.'
 if t=='@Composable':return 'Marks the next function as Compose UI content.'
 if t=='@HiltViewModel':return 'Registers the next ViewModel class for Hilt-generated construction.'
 if t.startswith('//'):return 'Source comment: '+t[2:].strip()
 if t in ['}', '},', '})', ')', '),', ') {', ')) {']:
  return {'}':'Closes the current Kotlin block or type.', '},':'Closes this callback/block and separates it from the next argument.', '})':'Closes the lambda and its surrounding call.', ')':'Closes the current argument or property list.', '),':'Closes this call and separates it from the next argument.', ') {':'Finishes the argument list and starts its function or UI-content block.', ')) {':'Finishes nested arguments and begins the content block.'}[t]
 raise ValueError(f'Unexplained line: {file}:{n} {line}')

